#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
#include <iostream>
static bool sameGraph(const Graph&a,const Graph&b){if(a.strings!=b.strings||a.elements.size()!=b.elements.size())return false;for(size_t i=0;i<a.elements.size();++i){const auto&x=a.elements[i];const auto&y=b.elements[i];if(x.type!=y.type||x.name!=y.name||x.attributes.size()!=y.attributes.size())return false;for(size_t j=0;j<x.attributes.size();++j){const auto&p=x.attributes[j];const auto&q=y.attributes[j];if(p.name!=q.name||p.type!=q.type||p.values.size()!=q.values.size())return false;for(size_t k=0;k<p.values.size();++k){const auto&v=p.values[k];const auto&w=q.values[k];if(v.wire!=w.wire||v.text!=w.text||v.reference!=w.reference||v.stringIndex!=w.stringIndex)return false;}}}return true;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("usage: test_session_document_delete_empty_dag benchmark.dmx");auto graph=loadGraph(argv[1]);SessionTimelineDocumentCandidate doc(graph);if(doc.dirty())throw std::runtime_error("document starts dirty");uint32_t target=UINT32_MAX,parent=UINT32_MAX;for(uint32_t i=0;i<graph.elements.size()&&target==UINT32_MAX;++i){const auto&t=graph.strings.at(graph.elements[i].type);if(t!="DmeCamera"&&t!="DmeDag"&&t!="DmeGameModel"&&t!="DmeLight"&&t!="DmeParticleSystem")continue;bool children=false;for(const auto&a:graph.elements[i].attributes)if(graph.strings.at(a.name)=="children")for(const auto&v:a.values)if(v.reference!=0xffffffffu&&v.reference!=0xfffffffeu)children=true;if(children)continue;for(uint32_t o=0;o<graph.elements.size()&&parent==UINT32_MAX;++o)if(o!=i)for(const auto&a:graph.elements[o].attributes)if((a.type==1||a.type==15)&&std::any_of(a.values.begin(),a.values.end(),[&](const auto&v){return v.reference==i;})){target=i;parent=o;break;}}
if(target==UINT32_MAX)throw std::runtime_error("no empty DAG with inbound reference in benchmark");auto removedType=graph.strings.at(graph.elements[target].type);auto incomingBefore=graph.elements[parent];const auto baseline=doc.graph();bool failed=false;try{doc.deleteEmptyDag(parent);}catch(const std::runtime_error&){failed=true;}if(!failed||!sameGraph(doc.graph(),baseline)||doc.dirty()||doc.undo())throw std::runtime_error("invalid deletion mutated document");if(!doc.deleteEmptyDag(target)||doc.graph().elements.size()+1!=baseline.elements.size()||!doc.dirty())throw std::runtime_error("delete mutation");for(const auto&e:doc.graph().elements)for(const auto&a:e.attributes)if((a.type==1||a.type==15))for(const auto&v:a.values)if(v.reference==target)throw std::runtime_error("deleted index remains referenced");const auto deleted=doc.graph();if(doc.undo()!=1||doc.dirty()||!sameGraph(doc.graph(),baseline))throw std::runtime_error("delete undo did not restore exact graph");if(doc.redo()!=1||!doc.dirty()||!sameGraph(doc.graph(),deleted))throw std::runtime_error("delete redo did not reproduce graph");const auto out="work/delete-empty-dag-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64())+".dmx";doc.saveAs(out.c_str());if(doc.dirty())throw std::runtime_error("saved deletion remains dirty");auto reopened=loadGraph(out.c_str());if(reopened.elements.size()!=deleted.elements.size())throw std::runtime_error("saved deletion reopen element count");if(doc.undo()!=1||!doc.dirty())throw std::runtime_error("undo after delete save dirty baseline");if(doc.redo()!=1||doc.dirty()||!sameGraph(doc.graph(),deleted))throw std::runtime_error("redo to saved deletion not clean");std::filesystem::remove(out);std::cout<<"empty_dag_delete_roundtrip=passed element="<<target<<" type="<<removedType<<" inbound_owner="<<parent<<" benchmark_elements="<<baseline.elements.size()<<" operations=reject_delete_save_reopen_undo_redo_save_undo_redo\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}